{-# LANGUAGE OverloadedStrings #-}
-- | Pieces of C++ source text the generated files share.
module Apigen.Language.Cpp.Text
    ( header
    , source
    , docBlock
    , summary
    , indent
    , braced
    , declaration
    , macroList
    , sizeExpr
    ) where

import           Apigen.SizeExpr (SizeExpr (..))
import           Data.Text       (Text)
import qualified Data.Text       as Text

preamble :: [Text]
preamble =
    [ "/* SPDX-License-Identifier: GPL-3.0-or-later"
    , " * Copyright © 2026 The TokTok team."
    , " */"
    , ""
    , "// Generated by hs-apigen from the toxcore headers: do not edit."
    , ""
    ]

header :: [Text] -> [Text] -> Text
header includes body = Text.unlines $
    preamble ++ ["#pragma once", ""] ++ map include includes ++ [""] ++ body

source :: [Text] -> [Text] -> Text
source includes body = Text.unlines $ preamble ++ map include includes ++ [""] ++ body

include :: Text -> Text
include i
    | "<" `Text.isPrefixOf` i = "#include " <> i
    | otherwise               = "#include \"" <> i <> "\""

docBlock :: Maybe Text -> [Text]
docBlock Nothing = []
docBlock (Just d) = ["/**"] ++ [ Text.stripEnd (" * " <> l) | l <- Text.lines d ] ++ [" */"]

summary :: Text -> Text
summary d = Text.unwords $ dropBrief $ Text.words $ case Text.splitOn "\n\n" (Text.strip d) of
    p : _ -> p
    []    -> d
  where
    dropBrief ("@brief" : ws) = ws
    dropBrief ws              = ws

indent :: [Text] -> [Text]
indent = map (\l -> if Text.null l then l else "    " <> l)

-- | @head { body }@, Mozilla style.
braced :: Text -> [Text] -> [Text]
braced h body = [h, "{"] ++ indent body ++ ["}"]

-- | @head { body };@: a class or struct.
declaration :: Text -> [Text] -> [Text]
declaration h body = [h, "{"] ++ map member body ++ ["};"]
  where
    member l
        | l `elem` ["public:", "protected:", "private:"] = l
        | otherwise = indent1 l
    indent1 l = if Text.null l then l else "    " <> l

-- | The lines of an X-macro's list: @macro(A) \\@ ... @macro(Z)@.
macroList :: [Text] -> [Text]
macroList names = zipWith line [1 :: Int ..] names
  where
    line i n = "    macro(" <> n <> ")" <> (if i < length names then " \\" else "")

sizeExpr :: (Text -> Text) -> SizeExpr -> Text
sizeExpr var e = case e of
    SizeNum n      -> Text.pack (show n)
    SizeVar v      -> var v
    -- Keeps it from wrapping before C checks it.
    SizeOp '-' a b -> operand a <> " < " <> operand b <> " ? 0 : " <> operand a <> " - " <> operand b
    SizeOp op a b  -> operand a <> " " <> Text.singleton op <> " " <> operand b
    SizeCall f as  -> "std::" <> f <> "(" <> Text.intercalate ", " (map (sizeExpr var) as) <> ")"
  where
    operand x = case x of
        SizeOp{} -> "(" <> sizeExpr var x <> ")"
        _        -> sizeExpr var x
